<?php require 'admin_guard.php';require 'admin_db.php';if($_SERVER['REQUEST_METHOD']==='POST'){$gid=$_POST['groupID'];mysqli_query($conn,"DELETE FROM group_info WHERE groupID='".mysqli_real_escape_string($conn,$gid)."' AND adminID='".mysqli_real_escape_string($conn,$adminID)."'");}$rows=mysqli_query($conn,"SELECT g.*,COUNT(j.student_UID) members FROM group_info g LEFT JOIN student_joins_group j ON j.groupID=g.groupID AND (j.leaveDate IS NULL OR j.leaveDate='0000-00-00') WHERE g.adminID='".mysqli_real_escape_string($conn,$adminID)."' GROUP BY g.groupID");?><!doctype html><html><head><title>Manage Groups</title><link rel="stylesheet" href="admin_pages.css"></head><body><div class="page"><div class="top"><h1>Manage Groups</h1><a class="btn" href="admin_dashboard.php">Dashboard</a></div><div class="panel"><table><tr><th>Group</th><th>Creator</th><th>Subject</th><th>Members</th><th>Action</th></tr><?php while($g=mysqli_fetch_assoc($rows)):?><tr><td><?=$g['groupID']?></td><td><?=$g['group_creator_uid']?></td><td><?=$g['targeted_subjects']?></td><td><?=$g['members']?>/5</td><td><form method="post"><input type="hidden" name="groupID" value="<?=$g['groupID']?>"><button class="danger">Delete/Reject</button></form></td></tr><?php endwhile;?></table></div></div></body></html>
